SELECT



    f.is_deleted = 0


        AND (p.product_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.product_code LIKE CONCAT('%', #{q.keyword}, '%')
        OR st.store_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR b.brand_name LIKE CONCAT('%', #{q.keyword}, '%'))


        AND f.user_id = #{q.userId}


        AND f.target_type = #{q.targetType}



        AND f.target_id = #{q.targetId}



        AND f.favorite_time >= #{q.beginTime}


        AND f.favorite_time <= #{q.endTime}


ORDER BY f.favorite_time DESC, f.id DESC

