UPDATE shop_consumer_favorite
SET is_deleted  = 1,
    update_by   = #{updateBy},
    update_time = NOW()
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND is_deleted = 0

UPDATE shop_consumer_favorite
SET is_deleted = 0,


        favorite_time = #{favoriteTime},


        favorite_time = NOW(),


    update_by   = #{updateBy},
    update_time = NOW()
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
